from pathlib import Path
import base64
import zlib

ROOT = Path(__file__).resolve().parents[1]
SETTINGS_B64 = ""
CHANGELOG_B64 = ""


def decode(value):
    return zlib.decompress(base64.b64decode(value)).decode("utf-8")


def write_text(path, text):
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8", newline="\n") as handle:
        handle.write(text)


write_text(ROOT / "Settings.lua", decode(SETTINGS_B64))

toc_path = ROOT / "AzerothQuesting.toc"
toc = toc_path.read_text(encoding="utf-8")
if "## Version: 0.3.0-beta.5" not in toc:
    raise SystemExit("Expected 0.3.0-beta.5 in AzerothQuesting.toc")
toc = toc.replace("## Version: 0.3.0-beta.5", "## Version: 0.3.0-beta.6", 1)
if "Settings.lua\n" not in toc:
    if "AzerothNetwork.lua\n" not in toc:
        raise SystemExit("AzerothNetwork.lua load line missing")
    toc = toc.replace("AzerothNetwork.lua\n", "AzerothNetwork.lua\nSettings.lua\n", 1)
write_text(toc_path, toc)

changelog_path = ROOT / "CHANGELOG.md"
changelog = changelog_path.read_text(encoding="utf-8")
header = "# Azeroth Questing Changelog\n\n"
if not changelog.startswith(header):
    raise SystemExit("Unexpected CHANGELOG.md header")
if "**VERSION 0.3.0 Beta 6 -" in changelog:
    raise SystemExit("Beta 6 changelog entry already exists")
changelog = header + decode(CHANGELOG_B64) + changelog[len(header):]
write_text(changelog_path, changelog)
